Algorithm FBRRS(problem_spec, time_limit, seed)
  // Fragment-Based Beam Refinement with Reinforced Sampling (task-agnostic)
  Init hooks: ENCODE, DECODE, COST, VALIDATE, REPAIR, OPERATORS, EXTRACT_FRAGMENTS, EXACT_SUBSOLVER
  beam := diverse_construct(problem_spec, seed, heuristics, beam_size) |> map(REPAIR, COST, VALIDATE)
  fragment_repo := initialize_from(beam, EXTRACT_FRAGMENTS); temp := init_temperature(time_limit)
  best := argmin_cost(beam)
  while not stop(time_limit, iterations, stagnation):
    candidates := {}
    for s in beam:
      candidates += stochastic_grow(s, fragment_repo, bias=fragment_scores, count=grow_per_parent)
      candidates += splice_fragments(s, beam.sample(), fragment_repo, OPERATORS.splice, count=splice_per_parent)
    candidates := REPAIR_FILTER_AND_SCORE(candidates, REPAIR, COST, VALIDATE)
    beam := top_k(beam ∪ candidates, k=beam_size, diversity_penalty=true)
    if periodic_mine(): fragment_repo := update_fragments(fragment_repo, beam, EXTRACT_FRAGMENTS, reward_propagation)
    if periodic_exact(): for sub in select_substructures(beam, budget): improved := EXACT_SUBSOLVER(sub, bb_budget); integrate_if_better(beam, improved)
    best := min(best, best_of(beam))
    temp := cool(temp); occasionally_accept_worse(beam, temp, anneal_rate)
  return DECODE(best)

